#if UNITY_EDITOR || DEVELOPMENT_BUILD
using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using TMPro;
using UnityEngine;
using UnityEngine.UI;
public sealed class MaritimeCityCapture:MonoBehaviour
{
 string folder;readonly List<string> results=new List<string>();
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Begin(){if(!Environment.GetCommandLineArgs().Contains("-maritime-city-capture"))return;string path=Path.GetFullPath(Path.Combine(Application.dataPath,"../Captures/MaritimeCities"));Directory.CreateDirectory(path);SaveGames.TestRoot=Path.Combine(path,"Saves");Directory.CreateDirectory(SaveGames.TestRoot);VariableSingleton.TestSavePath=Path.Combine(SaveGames.TestRoot,"checkpoint.besieged.json");var go=new GameObject("Maritime city verification");DontDestroyOnLoad(go);go.AddComponent<MaritimeCityCapture>().folder=path;}
 void Check(bool value,string label){if(!value)throw new Exception(label);results.Add("PASS "+label);}
 string State()=>JsonUtility.ToJson(VariableSingleton.Instance.CaptureState());
 Button Button(Transform root,string text)=>root.GetComponentsInChildren<Button>().First(b=>b.GetComponentInChildren<TMP_Text>()?.text==text);
 IEnumerator Start(){File.WriteAllText(Path.Combine(folder,"checks.txt"),"RUNNING");var stack=new Stack<IEnumerator>();stack.Push(Run());while(stack.Count>0){object next=null;bool more=false;Exception error=null;try{more=stack.Peek().MoveNext();if(more)next=stack.Peek().Current;}catch(Exception ex){error=ex;}if(error!=null){File.WriteAllLines(Path.Combine(folder,"details.txt"),results);File.WriteAllText(Path.Combine(folder,"checks.txt"),"FAILED "+error);Application.Quit(1);yield break;}if(!more){stack.Pop();continue;}if(next is IEnumerator nested)stack.Push(nested);else yield return next;}File.WriteAllLines(Path.Combine(folder,"details.txt"),results);File.WriteAllText(Path.Combine(folder,"checks.txt"),"MARITIME_CITY_CHECKS "+results.Count+" passed");Application.Quit();}
 IEnumerator Run(){Application.runInBackground=true;AudioListener.volume=0;yield return null;SaveMenu.StartCampaign(false);float deadline=Time.realtimeSinceStartup+20;while((!VariableSingleton.IsInitialized||FindObjectOfType<ManagerUI>()==null)&&Time.realtimeSinceStartup<deadline)yield return null;Check(VariableSingleton.IsInitialized,"campaign initialized");yield return new WaitForSecondsRealtime(.3f);CampaignHUD.Instance.DismissReport();var council=CouncilUI.For(FindObjectOfType<ManagerUI>());CountryDiplomacy.Ensure();
 foreach(var size in new[]{new Vector2Int(1600,900),new Vector2Int(1280,720)}){Screen.SetResolution(size.x,size.y,false);yield return new WaitForSecondsRealtime(.3f);
 foreach(string city in new[]{"genoa","venice"}){WarTheatreUI.Show();yield return null;string name=city=="genoa"?"Genoa":"Venice";var marker=GameObject.Find("Landmark · "+name);Check(marker!=null&&marker.GetComponent<Button>()!=null,name+" clickable map landmark");string before=State();marker.GetComponent<Button>().onClick.Invoke();yield return null;Check(MaritimeCityVisitUI.CurrentCity==city,name+" marker opens correct city");var view=GameObject.Find("Maritime city visit");Check(view!=null,name+" visit exists");Check(view.GetComponentsInChildren<RawImage>().Single().texture!=null,name+" art loaded");Canvas.ForceUpdateCanvases();foreach(var t in view.GetComponentsInChildren<TMP_Text>()){t.ForceMeshUpdate();Check(!t.isTextOverflowing,name+" text fits: "+t.text.Split('\n')[0]);}Check(State()==before,name+" visit leaves campaign and RNG unchanged");yield return Capture(city+"-"+size.x);Button(view.transform,"Return to the map").onClick.Invoke();yield return null;Check(GameObject.Find("Maritime city visit")==null&&GameObject.Find("War Beyond the Walls map")!=null,name+" Return preserves map");
 marker=GameObject.Find("Landmark · "+name);marker.GetComponent<Button>().onClick.Invoke();yield return null;ControlSingleton.Instance.GoBack();yield return null;Check(GameObject.Find("Maritime city visit")==null&&GameObject.Find("War Beyond the Walls map")!=null,name+" Back closes visit before map");
 marker.GetComponent<Button>().onClick.Invoke();yield return null;view=GameObject.Find("Maritime city visit");var diplomacy=Button(view.transform,"Diplomacy with "+name);Check(diplomacy.interactable,name+" diplomacy enabled");int gold=DailyLifeEvents.I("iMoney"),turn=VariableSingleton.Turn;diplomacy.onClick.Invoke();yield return null;Check(GameObject.Find("Maritime city visit")==null&&GameObject.Find("War Beyond the Walls map")==null,name+" diplomacy closes visit and map");Check(GameObject.Find("Council screen").GetComponentsInChildren<TMP_Text>().Any(t=>t.text==CountryDiplomacy.Definitions[CountryDiplomacy.Index(city)].Name),name+" correct diplomatic court opened");Check(gold==DailyLifeEvents.I("iMoney")&&turn==VariableSingleton.Turn,name+" diplomacy navigation spends no gold or time");council.Hide();yield return null;
 }} }
 IEnumerator Capture(string name){yield return new WaitForSecondsRealtime(.1f);Canvas.ForceUpdateCanvases();var go=new GameObject("Maritime capture camera",typeof(Camera));var camera=go.GetComponent<Camera>();camera.orthographic=true;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=ImperialTheme.Navy;camera.nearClipPlane=.1f;camera.farClipPlane=100;var canvases=FindObjectsOfType<Canvas>().Where(c=>c.isRootCanvas).ToArray();var modes=canvases.Select(c=>c.renderMode).ToArray();var cameras=canvases.Select(c=>c.worldCamera).ToArray();var distances=canvases.Select(c=>c.planeDistance).ToArray();var target=RenderTexture.GetTemporary(Screen.width,Screen.height,24);var previous=RenderTexture.active;Texture2D shot=null;try{camera.targetTexture=target;foreach(var c in canvases){c.renderMode=RenderMode.ScreenSpaceCamera;c.worldCamera=camera;c.planeDistance=10;}Canvas.ForceUpdateCanvases();camera.Render();RenderTexture.active=target;shot=new Texture2D(target.width,target.height,TextureFormat.RGB24,false);shot.ReadPixels(new Rect(0,0,target.width,target.height),0,0);shot.Apply();File.WriteAllBytes(Path.Combine(folder,name+".png"),shot.EncodeToPNG());}finally{RenderTexture.active=previous;for(int i=0;i<canvases.Length;i++){canvases[i].renderMode=modes[i];canvases[i].worldCamera=cameras[i];canvases[i].planeDistance=distances[i];}camera.targetTexture=null;RenderTexture.ReleaseTemporary(target);if(shot!=null)Destroy(shot);Destroy(go);}}
}
#endif
